-- migrations/0012_exchange_seed.sql
-- Curated seed data for the DEX/CEX Graveyard (dead_exchanges/mid_exchanges,
-- see 0011_exchange_analysis.sql). 34 dead_exchanges + 10 mid_exchanges rows
-- across kind='dex'/'cex', plus 4 graveyard_meta narrative rows. The mixed
-- centralized-finance trend note is retained under an explicit archive key and
-- is not served as the public exchange-only CEX trend.
--
-- Sourced from independently-verified research: two research passes (DEX
-- landscape/history, CEX landscape/history), a dedicated adversarial fact-check
-- workflow on every "this week" (2026-07-20 to 2026-07-27) claim (2 independent
-- skeptics per claim, empowered to refute), and a data-scientist + external-
-- researcher comparative-analysis pass. Every dollar figure, date, and % traces
-- to a cited source in the row's `sources` column. No manual transaction
-- wrapper — D1 wraps --file execution in its own (see 0007_mid_chains_stuck.sql).
--
-- Named-individual claims follow CLAUDE.md §1.5: court-convicted cases (Sam
-- Bankman-Fried/FTX, Alex Mashinsky/Celsius, Faruk Fatih Özer/Thodex) are
-- stated as fact with citation; unresolved allegations (Gerald Cotten/
-- QuadrigaCX — died before any charges; Zhang Jian/FCoin — a researcher
-- allegation, never charged; Zhu Juntao/Hodlnaut — charged, not convicted;
-- Nenter "Nathan" Chow/BitMart — his own account, independently reported by
-- The Block, cause of his removal left unresolved) are phrased as allegations
-- throughout, never as fact of guilt.

INSERT OR REPLACE INTO dead_exchanges (slug, kind, name, launched, metric_label, peak_metric, current_metric, drawdown_pct, peak_date, collapse_date, why, outlook, verdict, sources, profile, updated_at) VALUES
  ('kyberswap', 'dex', 'KyberSwap Elastic', NULL, 'TVL', 71000000, 3000000, 95.8, NULL, '2023-11-22',
  'KyberSwap''s concentrated-liquidity Elastic protocol was exploited on Nov 22-23 2023 for roughly $48.9-54.7M via a tick-crossing/rounding flaw in its liquidity math, hitting pools across 17 chains. TVL collapsed from a $71M peak to under $3M within days as liquidity providers pulled out. The team negotiated with the attacker but recovered only a fraction of funds, and the separate legacy KyberSwap Classic product was formally discontinued on Mar 26 2024.',
  'No credible revival path — the exploited liquidity math was core to Elastic''s design, LPs have not returned, and Classic is formally shut down. Treat as permanently defunct.',
  'defunct',
  '[{"title": "Post Mortem: KyberSwap Elastic Exploit November 2023", "url": "https://blog.kyberswap.com/post-mortem-kyberswap-elastic-exploit/"}, {"title": "KyberSwap Crypto Platform $54 Million Hack", "url": "https://therecord.media/kyberswap-crypto-platform-54-million-hack"}]',
  '{"cause_tags": ["exploit_hack", "team_abandonment"], "founded": null, "chains": ["Ethereum", "BNB Chain", "Polygon", "Avalanche", "Arbitrum", "Optimism"]}',
  datetime('now')),
  ('platypus-finance', 'dex', 'Platypus Finance', '2021-11', 'TVL', 1250000000, 28700, 99.98, '2022-03', '2023-02-16',
  'Platypus''s single-sided stableswap AMM on Avalanche was exploited twice — an $8.5M flash-loan attack in Feb 2023 and a further $2.2M exploit in Oct 2023, both rooted in a flawed solvency check that let an attacker borrow against collateral that should have stayed locked. TVL, which peaked near $1.25B in Mar 2022, has fallen to roughly $28.7K — an essentially total wipeout.',
  'No functioning product or liquidity remains; the solvency-check flaw that enabled both exploits was never trusted enough by users to rebuild TVL. Treat as permanently defunct.',
  'defunct',
  '[{"title": "Platypus Finance Hack Analysis", "url": "https://immunefi.com/blog/industry-trends/platypus-finance-hack-analysis/"}, {"title": "DefiLlama — Platypus Finance", "url": "https://defillama.com/protocol/platypus-finance"}]',
  '{"cause_tags": ["exploit_hack", "security_failure"], "founded": "2021-11", "chains": ["Avalanche"]}',
  datetime('now')),
  ('deus-finance', 'dex', 'Deus Finance', NULL, 'TVL', NULL, NULL, NULL, NULL, '2023-05',
  'Deus Finance suffered three separate exploits targeting its Muon oracle and DEI stablecoin-minting logic: a $3M attack in Mar 2022, a further $13.4M exploit in Apr 2022, and a $6M+ exploit in May 2023. Its DEI stablecoin, pitched as a decentralized dollar alternative, permanently lost its $1 peg and never recovered.',
  'With DEI permanently depegged and three separate oracle-related exploits on record, there is no credible path back to a functioning stablecoin or AMM. Treat as permanently defunct.',
  'defunct',
  '[{"title": "DEUS Finance loses $6M following stablecoin hack", "url": "https://cointelegraph.com/news/deus-finance-loses-6m-following-stablecoin-hack"}]',
  '{"cause_tags": ["exploit_hack", "security_failure"], "founded": null, "chains": ["Ethereum", "Polygon"]}',
  datetime('now')),
  ('mango-markets', 'dex', 'Mango Markets', '2021-08', 'TVL', NULL, NULL, NULL, NULL, '2022-10-11',
  'Mango Markets, a Solana margin/perps exchange built on the Serum orderbook, was exploited for $116M on Oct 11 2022 when an attacker manipulated the price of the illiquid MNGO perpetual to inflate their collateral and borrow out the treasury. The DAO later negotiated a partial return of funds, the SEC settled charges against the attacker in Sept 2024, and Mango Markets fully wound down operations on Jan 13 2025.',
  'The exchange has formally shut down; there is no product to revive. Treat as permanently defunct.',
  'defunct',
  '[{"title": "How Market Manipulation Led to a $100M Exploit on Solana DeFi Exchange Mango", "url": "https://www.coindesk.com/markets/2022/10/12/how-market-manipulation-led-to-a-100m-exploit-on-solana-defi-exchange-mango"}, {"title": "Mango Markets to Wind Down in Wake of SEC Settlement, DAO Battle", "url": "https://www.theblock.co/post/334172/mango-markets-to-wind-down-in-wake-of-sec-settlement-dao-battle"}]',
  '{"cause_tags": ["exploit_hack", "security_failure", "regulatory"], "founded": "2021-08", "chains": ["Solana"]}',
  datetime('now')),
  ('mirror-protocol', 'dex', 'Mirror Protocol', '2020-12', 'TVL', NULL, NULL, NULL, NULL, '2022-05',
  'Mirror Protocol, a Terra-based synthetic-assets AMM for mirroring real-world stocks, was exploited for roughly $90M in Oct 2021 via a minting-price manipulation bug. It did not recover before the far larger blow: Terra''s UST stablecoin collapsed in May 2022, wiping out the entire Terra DeFi ecosystem Mirror depended on, and its price oracle feeds were pulled entirely in Aug 2022, ending any remaining functionality.',
  'With its host chain''s stablecoin permanently collapsed and its own oracle feeds withdrawn, Mirror has no remaining infrastructure to operate on. Treat as permanently defunct.',
  'defunct',
  '[{"title": "Mirror Protocol: Development and Crisis Explained", "url": "https://www.gate.com/learn/articles/mirror-protocol-development-and-crisis/804"}]',
  '{"cause_tags": ["exploit_hack", "wrong_ecosystem_bet"], "founded": "2020-12", "chains": ["Terra"]}',
  datetime('now')),
  ('serum', 'dex', 'Serum', '2020-08', 'TVL', NULL, NULL, NULL, NULL, '2022-11',
  'Serum, a central-limit-orderbook DEX on Solana, was built and controlled by FTX and Alameda Research, who held its upgrade authority. When FTX and Alameda collapsed in Nov 2022, the project lost both its core team and the trusted party controlling its smart contracts, and the wider Solana ecosystem judged it unsafe to keep building on. Developers abandoned Serum and forked its codebase into OpenBook, a community-controlled successor.',
  'The project has no team and no community confidence in its FTX/Alameda-controlled contracts; usage has fully migrated to the OpenBook fork. Treat as permanently defunct.',
  'defunct',
  '[{"title": "Serum Exchange Rendered Defunct Following the Collapse of Alameda and FTX", "url": "https://cointelegraph.com/news/serum-exchange-rendered-defunct-following-the-collapse-of-alameda-and-ftx"}]',
  '{"cause_tags": ["team_abandonment", "centralization"], "founded": "2020-08", "chains": ["Solana"]}',
  datetime('now')),
  ('spiritswap', 'dex', 'SpiritSwap', '2021-04', 'TVL', 374000000, 340000, 99.9, '2022-01', '2023-07',
  'SpiritSwap, one of the earliest incentivized DEXs on Fantom, saw its treasury and liquidity drained after the Jul 2023 collapse of the Multichain bridge, on which much of its cross-chain liquidity depended. TVL, which had peaked at $374M in Jan 2022 on mercenary yield-farming incentives, fell to roughly $340K.',
  'The team briefly attempted a rescue after the Multichain collapse, but liquidity and users never returned at scale. Treat as effectively defunct.',
  'defunct',
  '[{"title": "Fantom DEX rescued at eleventh hour following planned shutdown", "url": "https://cointelegraph.com/news/fantom-dex-rescued-at-eleventh-hour-following-planned-shutdown"}]',
  '{"cause_tags": ["bridge_hack", "mercenary_tvl"], "founded": "2021-04", "chains": ["Fantom"]}',
  datetime('now')),
  ('solidly', 'dex', 'Solidly', '2022-01', 'TVL', 2240000000, 3250, 99.99, NULL, '2022-03-06',
  'Solidly, a Fantom ve(3,3) AMM launched in Jan 2022 by prolific DeFi developer Andre Cronje, collapsed within weeks of launch when Cronje announced his abrupt exit from DeFi entirely on Mar 6 2022, crashing its token roughly 75% in a single day. TVL, which had reached as high as ~$2.24B on launch-week incentive farming, fell as low as ~$3.25K.',
  'The founder''s public exit destroyed confidence immediately and liquidity never returned. Treat as permanently defunct.',
  'defunct',
  '[{"title": "Dozens of Tokens Tumble as Prolific Developer Andre Cronje Calls It Quits", "url": "https://www.coindesk.com/business/2022/03/06/dozens-of-tokens-tumble-as-prolific-developer-andre-cronje-calls-it-quits"}]',
  '{"cause_tags": ["team_abandonment", "mercenary_tvl"], "founded": "2022-01", "chains": ["Fantom"]}',
  datetime('now')),
  ('bunni', 'dex', 'Bunni', NULL, 'TVL', NULL, NULL, NULL, NULL, '2025-09-02',
  'Bunni, a Uniswap v4 hook-based DEX on Ethereum and Unichain, was exploited on Sept 2 2025 for roughly $8.4M via a rounding error in its liquidity-density-function hook, drained through a flash loan. The team shut the protocol down entirely on Oct 23 2025, stating it could not afford to rebuild the security needed for a safe relaunch.',
  'The team has explicitly shut down rather than relaunch. Treat as permanently defunct.',
  'defunct',
  '[{"title": "Bunni DEX Shuts Down, Cites Recovery Costs After $8.4M Exploit", "url": "https://www.coindesk.com/business/2025/10/23/bunni-dex-shuts-down-cites-recovery-costs-after-usd8-4m-exploit"}]',
  '{"cause_tags": ["exploit_hack", "team_abandonment"], "founded": null, "chains": ["Ethereum", "Unichain"]}',
  datetime('now')),
  ('waultswap', 'dex', 'WaultSwap', '2021-04', 'WEX token price', NULL, 0.000007, 99.99, NULL, '2021-08-04',
  'WaultSwap, the flagship DEX of Wault Finance on BNB Chain, was exploited on Aug 4 2021 in an attack that SlowMist''s analysis attributes to an economic-design flaw in the USDT/WUSD peg-arbitrage mechanism, not a proven insider rug. Its WEX governance token never recovered, trading around $0.000007 today, roughly -99.99% off its highs.',
  'No meaningful liquidity or team activity remains around the token or protocol. Treat as permanently defunct.',
  'defunct',
  '[{"title": "SlowMist: An Analysis of the Attack on Wault Finance", "url": "https://slowmist.medium.com/slowmist-an-analysis-of-the-attack-on-wault-finance-5874100b3b73"}]',
  '{"cause_tags": ["exploit_hack"], "founded": "2021-04", "chains": ["BNB Chain"]}',
  datetime('now')),
  ('gmx-v1', 'dex', 'GMX V1 (GLP)', '2021-09', 'TVL', NULL, NULL, NULL, NULL, '2025-07-09',
  'GMX V1, the original GLP-backed perpetuals product on Arbitrum and Avalanche, was exploited on Jul 9 2025 via a reentrancy bug for roughly $42M gross (about $2M net after the attacker returned funds for a negotiated 10% white-hat bounty). GLP minting and redemption were permanently disabled afterward. This affects the V1/GLP product line specifically — GMX V2 continues operating unaffected under the same brand.',
  'GLP minting/redemption is permanently disabled with no announced plan to restore it; V1 is being wound down in favor of V2. Treat V1 specifically as defunct.',
  'defunct',
  '[{"title": "Decentralized Exchange GMX Exploited for $42M, Offers Hacker 10% White-Hat Bounty", "url": "https://www.coindesk.com/business/2025/07/09/decentralized-exchange-gmx-exploited-for-usd42m-offers-hacker-10-white-hat-bounty"}]',
  '{"cause_tags": ["exploit_hack", "security_failure"], "founded": "2021-09", "chains": ["Arbitrum", "Avalanche"]}',
  datetime('now')),
  ('saddle-finance', 'dex', 'Saddle Finance', '2021-01', 'TVL', NULL, NULL, NULL, NULL, '2023-08-08',
  'Saddle Finance, a Curve-style stableswap AMM on Ethereum, was never hacked — its DAO instead voted to dissolve the project via SIP-54 on Aug 8 2023 after years of failing to gain meaningful traction against Curve''s dominance in the stableswap niche.',
  'The DAO has formally voted to wind down; this is a deliberate closure, not a recoverable setback. Treat as permanently defunct.',
  'defunct',
  '[{"title": "Venture-Backed Saddle Finance Proposes Wind-Down, Dissolution", "url": "https://www.coindesk.com/tech/2023/08/08/venture-backed-saddle-finance-proposes-wind-down-dissolution"}]',
  '{"cause_tags": ["competition", "no_killer_app"], "founded": "2021-01", "chains": ["Ethereum"]}',
  datetime('now')),
  ('uranium-finance', 'dex', 'Uranium Finance', '2021-04', 'URF token price', NULL, 0, 100.0, NULL, '2021-04-28',
  'Uranium Finance, a Uniswap V2 fork on BNB Chain, was exploited on Apr 28 2021 for roughly $50M when an error in its liquidity-migration calculation let an attacker drain paired liquidity during a contract upgrade. Its URF token is now worthless, trading at $0.00.',
  'The token has no remaining value and the protocol has no active development. Treat as permanently defunct.',
  'defunct',
  '[{"title": "Uranium Finance Exploit", "url": "https://www.crypto-news-flash.com/uranium-finance-exploit/"}]',
  '{"cause_tags": ["exploit_hack"], "founded": "2021-04", "chains": ["BNB Chain"]}',
  datetime('now')),
  ('mt-gox', 'cex', 'Mt. Gox', '2010', 'assets under management', NULL, 486500000, NULL, NULL, '2014-02-28', 'Mt. Gox, once the dominant global bitcoin exchange, filed for bankruptcy protection in Tokyo District Court on February 28, 2014, after disclosing that roughly 850,000 BTC had disappeared in a hack — including an estimated 750,000 BTC in customer-owned coins — worth an estimated $473-500 million at the time. Mt. Gox remains, over a decade later, in creditor rehabilitation and repayment proceedings, one of the longest-running unwound exchange failures in the industry''s history.', 'Still working through creditor rehabilitation and BTC repayments more than a decade after the collapse — the slowest resolution in this dataset.', 'defunct', '[{"title":"Mt. Gox Files For Bankruptcy — NPR","url":"https://www.npr.org/sections/thetwo-way/2014/02/28/283863219/mtgox-files-for-bankruptcy"},{"title":"Mt. Gox Files for Bankruptcy — TechCrunch","url":"https://techcrunch.com/2014/02/28/mt-gox-files-for-bankruptcy"}]', '{"cause_tags":["exploit_hack","security_failure"],"launched":"2010","amount_lost_btc":"~850,000 BTC (~750,000 customer-owned)","amount_lost_usd_at_time":"~$473-500M (2014 valuation)","bankruptcy_date":"2014-02-28","bankruptcy_court":"Tokyo District Court","status":"still in creditor rehabilitation/repayment proceedings as of 2026, over a decade after filing","cause":"hack exploiting a transaction-malleability vulnerability"}', datetime('now')),
  ('quadrigacx', 'cex', 'QuadrigaCX', '2013', 'assets under management', NULL, 190000000, NULL, NULL, '2019-01', 'QuadrigaCX, Canada''s largest crypto exchange, collapsed in January-February 2019 after founder and CEO Gerald Cotten died unexpectedly on December 9, 2018, reportedly the sole holder of the private keys to the exchange''s cold wallets. Roughly C$250 million (about $190 million) in customer funds became inaccessible. A subsequent Ontario Securities Commission (OSC) investigation later alleged that Cotten had misused customer funds for personal speculative trading in the years before his death — an allegation made after Cotten''s death and never tested against him in any criminal proceeding, since no charges were ever filed. EY, appointed as trustee, recovered only about $30-34 million in the ensuing liquidation, and creditors were ultimately paid roughly 13% of their claims.', 'Liquidation concluded years ago with only a fraction of funds recovered; there is no prospect of the exchange reopening or of further meaningful recovery.', 'defunct', '[{"title":"QuadrigaCX collapse coverage — CBC","url":"https://www.cbc.ca/lite/story/1.5005236"},{"title":"Gerald Cotten and Quadriga: Unraveling Crypto''s Biggest Mystery — CoinDesk","url":"https://www.coindesk.com/markets/2021/06/29/gerald-cotten-and-quadriga-unraveling-cryptos-biggest-mystery"}]', '{"cause_tags":["commingled_funds"],"launched":"2013","individuals":[{"name":"Gerald Cotten","role":"founder/CEO","status":"deceased; never charged criminally","note":"Died Dec 9, 2018. An OSC investigation later ALLEGED he misused customer funds for personal speculative trading — a regulatory finding/allegation, not a criminal conviction, since he died before any charges could be filed. Never state as settled fact of guilt."}],"amount_owed_cad":"~C$250M","amount_owed_usd":"~$190M","recovered_by_trustee_usd":"~$30-34M (EY, trustee)","creditor_repayment_pct":"~13% of claims","collapse_window":"Jan-Feb 2019"}', datetime('now')),
  ('ftx', 'cex', 'FTX', '2019', 'assets under management', NULL, 8000000000, NULL, NULL, '2022-11', 'FTX, once the world''s second-largest crypto exchange, collapsed within roughly ten days in November 2022 (Nov 2-12) after a CoinDesk report on Alameda Research''s balance sheet exposed extensive commingling between FTX customer deposits and its affiliated trading firm Alameda, revealing an $8 billion shortfall in customer funds. Founder Sam Bankman-Fried was convicted on multiple counts of fraud; he was sentenced to 25 years in prison, and his appeal was denied on June 12, 2026, upholding both conviction and sentence. As of March 2026, FTX''s bankruptcy estate had repaid roughly 96.6% of allowed claims, totaling about $10.3 billion distributed to creditors.', 'Bankruptcy estate distributions are substantially complete (96.6% of claims as of March 2026); Bankman-Fried''s conviction stands after his June 2026 appeal denial. FTX will not reopen.', 'defunct', '[{"title":"Sam Bankman-Fried Loses Appeal, 25-Year Sentence Upheld — CryptoTimes","url":"https://www.cryptotimes.io/2026/06/12/sam-bankman-fried-loses-appeal-25-year-prison-sentence-for-ftx-fraud-upheld/"},{"title":"FTX Set to Repay Creditors $2.2 Billion This Month — CoinDesk","url":"https://www.coindesk.com/business/2026/03/18/sam-bankman-fried-s-bankrupt-exchange-ftx-set-to-repay-creditors-usd2-2-billion-this-month"}]', '{"cause_tags":["commingled_funds","insider_fraud"],"launched":"2019","individuals":[{"name":"Sam Bankman-Fried","role":"founder/CEO","status":"convicted; sentenced to 25 years; appeal denied June 12, 2026","note":"Court-convicted — safe to state as settled fact."}],"shortfall_usd":"$8B customer shortfall","trigger":"CoinDesk report on Alameda Research balance sheet, exposing FTX/Alameda fund commingling","claims_repaid_pct":"~96.6% as of March 2026","total_distributed_usd":"~$10.3B"}', datetime('now')),
  ('celsius', 'cex', 'Celsius Network', '2017', 'assets under management', NULL, NULL, NULL, NULL, '2022-07-13', 'Celsius Network, a crypto lending/yield platform, froze customer withdrawals in June 2022 and filed for Chapter 11 bankruptcy on July 13, 2022, with estimates of the shortfall ranging from roughly $4.7 billion to $7 billion. Founder and CEO Alex Mashinsky was later convicted — he pleaded guilty to commodities and securities fraud and was sentenced to 12 years in prison on May 8, 2025.', 'Mashinsky''s conviction and sentencing are final; the platform does not operate.', 'defunct', '[{"title":"Celsius Founder Alex Mashinsky Sentenced to 12 Years for Fraud — CoinDesk","url":"https://www.coindesk.com/policy/2025/05/08/celsius-founder-alex-mashinsky-sentenced-to-12-years-in-prison-for-fraud"},{"title":"Celsius CEO Alex Mashinsky Sentenced to 12 Years in Crypto Fraud Case — CNBC","url":"https://www.cnbc.com/2025/05/08/celsius-ceo-alex-mashinsky-sentenced-to-12-years-in-crypto-fraud-case.html"}]', '{"cause_tags":["insider_fraud","commingled_funds"],"launched":"2017","individuals":[{"name":"Alex Mashinsky","role":"founder/CEO","status":"convicted; pleaded guilty to commodities/securities fraud; sentenced to 12 years on May 8, 2025","note":"Court-convicted — safe to state as settled fact."}],"shortfall_range_usd":"~$4.7-7B (estimates vary)","withdrawals_frozen":"June 2022","bankruptcy_filed":"2022-07-13"}', datetime('now')),
  ('voyager-digital', 'cex', 'Voyager Digital', NULL, 'assets under management', NULL, NULL, NULL, NULL, '2022-07-05', 'Voyager Digital, a crypto brokerage, filed for Chapter 11 bankruptcy on July 5, 2022, after Three Arrows Capital (3AC) defaulted on roughly $650 million in exposure to the firm, triggering insolvency. A rescue deal in which FTX would acquire Voyager''s assets collapsed when FTX itself failed weeks later. A subsequent $1.02-1.3 billion deal with Binance.US also collapsed, with Binance.US walking away in April 2023. Customers ultimately received an initial distribution of roughly 35.72% of their claims.', 'Both proposed rescue deals (FTX, then Binance.US) fell through; customers received only partial recovery through the bankruptcy process.', 'defunct', '[{"title":"Binance to Acquire Voyager Assets Weeks After FTX Deal Fell Through — CNBC","url":"https://www.cnbc.com/2022/12/19/binance-to-acquire-voyager-assets-weeks-after-ftx-deal-fell-through-bankruptcy.html"},{"title":"Bankrupt Crypto Broker Voyager Cleared to Repay Creditors — Decrypt","url":"https://decrypt.co/140547/bankrupt-crypto-broker-voyager-cleared-repay-creditors"}]', '{"cause_tags":["bank_run"],"trigger":"Three Arrows Capital default (~$650M exposure)","bankruptcy_filed":"2022-07-05","failed_deals":["FTX acquisition of Voyager assets (collapsed when FTX itself failed)","Binance.US deal worth $1.02-1.3B (Binance.US withdrew April 2023)"],"initial_creditor_repayment_pct":"~35.72%"}', datetime('now')),
  ('blockfi', 'cex', 'BlockFi', '2017', 'assets under management', NULL, 1200000000, NULL, NULL, '2022-11-28', 'BlockFi, a crypto lending platform, filed for bankruptcy on November 28, 2022, citing roughly $1.2 billion of exposure to FTX and Alameda Research after FTX''s collapse days earlier. Court filings put the total range of liabilities owed to more than 100,000 creditors as wide as $1 billion to $10 billion.', 'Wound down through Chapter 11; no relaunch.', 'defunct', '[{"title":"BlockFi Files for Bankruptcy as FTX Fallout Spreads — CNBC","url":"https://www.cnbc.com/2022/11/28/blockfi-files-for-bankruptcy-as-ftx-fallout-spreads.html"}]', '{"cause_tags":["bank_run","ftx_contagion"],"launched":"2017","ftx_alameda_exposure_usd":"~$1.2B","liabilities_range_usd":"$1B-$10B (wide court-filing range, 100,000+ creditors)","bankruptcy_filed":"2022-11-28"}', datetime('now')),
  ('cryptopia', 'cex', 'Cryptopia', NULL, 'assets under management', NULL, 16000000, NULL, NULL, '2019-05-15', 'Cryptopia, a New Zealand-based exchange, was hacked on January 14, 2019, losing an estimated $16 million in ETH and ERC-20 tokens to a hot/cold wallet security failure; the company entered liquidation on May 15, 2019. This hack loss is distinct from a much later, separate event: liquidators eventually distributed NZ$400 million (about $225 million) of Cryptopia''s remaining, un-hacked customer holdings — assets that were never stolen — to more than 10,000 verified users, with that distribution completing by December 20, 2024.', 'Liquidation formally wound down; remaining (un-hacked) customer holdings were returned by December 2024, though the original $16M hack loss was not itself recovered.', 'defunct', '[{"title":"Hacked New Zealand Exchange Cryptopia Appoints Liquidators — Cointelegraph","url":"https://cointelegraph.com/news/hacked-new-zealand-exchange-cryptopia-appoints-liquidators-trading-suspended"},{"title":"Cryptopia Hack Liquidators Distribute $225 Million in Crypto to Victims — Brave New Coin","url":"https://bravenewcoin.com/insights/cryptopia-hack-liquidators-distribute-225-million-in-crypto-to-victims"}]', '{"cause_tags":["security_failure","exploit_hack"],"hq":"New Zealand","hack_date":"2019-01-14","hack_loss_usd":"~$16M (ETH/ERC-20)","liquidation_start":"2019-05-15","separate_later_distribution":"NZ$400M (~$225M) of remaining un-hacked holdings distributed to 10,000+ verified users by 2024-12-20 — NOT a recovery of the hack loss; keep these two figures distinct."}', datetime('now')),
  ('prime-trust', 'cex', 'Prime Trust', NULL, 'assets under management', NULL, 500000000, NULL, NULL, '2023-08-14', 'Prime Trust, an FTX-linked crypto custodian, filed for Chapter 11 bankruptcy on August 14, 2023, with liabilities of up to $500 million. Nevada regulators found that Prime Trust had used customer funds to cover withdrawals since December 2021 and had invested customer funds in Terra/LUNA, according to the Nevada Financial Institutions Division as reported by CoinDesk — a regulatory finding of fund misappropriation, not a stated criminal conviction of any named individual.', 'Wound down through Chapter 11 following the Nevada regulatory findings.', 'defunct', '[{"title":"Prime Trust Files for Bankruptcy Protection — Coinspeaker","url":"https://www.coinspeaker.com/prime-trust-bankruptcy-protection/"},{"title":"Prime Trust Has Shortfall of Customer Funds, Nevada Regulator Says — CoinDesk","url":"https://www.coindesk.com/policy/2023/06/22/prime-trust-has-shortfall-of-customer-funds-nevada-regulator-says"}]', '{"cause_tags":["commingled_funds"],"liabilities_usd":"up to $500M","bankruptcy_filed":"2023-08-14","regulatory_finding":"Nevada Financial Institutions Division found Prime Trust used customer funds to cover withdrawals since Dec 2021 and invested customer funds in Terra/LUNA. No named individual charged in the given record."}', datetime('now')),
  ('coinflex', 'cex', 'CoinFLEX', '2019', 'assets under management', NULL, 84000000, NULL, NULL, '2022-06-23', 'CoinFLEX halted withdrawals on June 23, 2022, after a large counterparty default. CoinFLEX itself publicly identified the counterparty as Roger Ver, owing $47 million — a claim CoinFLEX made in its own public statements and litigation, not independently confirmed by outside authorities. The disputed amount grew to $84 million through litigation. CoinFLEX restructured in Seychelles in August 2022 and issued "Recovery Value USD" tokens to affected users.', 'Restructured via a token-based recovery scheme rather than a clean wind-down; the Roger Ver dispute remained in litigation.', 'defunct', '[{"title":"CoinFLEX to Launch a $47M Recovery Token to Solve Withdrawal Issues — CoinDesk","url":"https://www.coindesk.com/business/2022/06/27/coinflex-to-launch-a-47m-recovery-token-to-solve-withdrawal-issues"},{"title":"Crypto Exchange CoinFLEX Claims Roger Ver Is Behind $47 Million Debt — CNBC","url":"https://www.cnbc.com/2022/06/29/crypto-exchange-coinflex-claims-roger-ver-is-behind-47-million-debt.html"}]', '{"cause_tags":["bank_run"],"launched":"2019","withdrawals_halted":"2022-06-23","counterparty_dispute":{"amount_initial_usd":47000000,"amount_litigated_usd":84000000,"counterparty_named_by":"CoinFLEX itself, publicly (as Roger Ver) — NOT independently confirmed by outside authorities","note":"Attribute this claim to CoinFLEX; do not state as an independently confirmed fact."},"restructuring":"Seychelles, Aug 2022, issued \"Recovery Value USD\" tokens"}', datetime('now')),
  ('vauld', 'cex', 'Vauld', NULL, 'assets under management', NULL, 400000000, NULL, NULL, '2022-07-04', 'Vauld, a Singapore-based crypto lender, halted operations on July 4, 2022, owing more than $400 million to creditors. The collapse was triggered by contagion from the Celsius withdrawal freeze, which began roiling the market on June 12, 2022. A payback scheme was later approved by more than 90% of creditors.', 'Wound down via an approved creditor payback scheme rather than a clean relaunch.', 'defunct', '[{"title":"Crypto Lender Vauld Halts Withdrawals as Market Crash Takes Its Toll — CNBC","url":"https://www.cnbc.com/2022/07/04/crypto-lender-vauld-halts-withdrawals-as-market-crash-takes-its-toll-.html"}]', '{"cause_tags":["bank_run"],"hq":"Singapore","amount_owed_usd":"$400M+","ops_halted":"2022-07-04","trigger":"Celsius-freeze contagion starting 2022-06-12","resolution":"payback scheme approved by 90%+ of creditors"}', datetime('now')),
  ('zipmex', 'cex', 'Zipmex', '2018', 'assets under management', NULL, NULL, NULL, NULL, '2022-07-20', 'Zipmex, a Singapore/Thailand-based exchange, paused withdrawals on July 20, 2022, amid contagion from its exposure to Celsius and Three Arrows Capital via its "ZipUp" yield product, compounded when an investor missed a takeover payment. Unlike most of its 2022-cohort peers, Zipmex later reopened some withdrawals rather than remaining fully frozen.', 'Partially reopened withdrawals — an unusual outcome versus its 2022 peer cohort — though the exchange never returned to full pre-freeze operation.', 'defunct', '[{"title":"Crypto Exchange Zipmex Suspends Withdrawals Citing Market Volatility — CoinDesk","url":"https://www.coindesk.com/markets/2022/07/20/crypto-exchange-zipmex-suspends-withdrawals-citing-market-volatility/"}]', '{"cause_tags":["bank_run"],"hq":"Singapore/Thailand","launched":"2018","withdrawals_paused":"2022-07-20","trigger":"Celsius/3AC exposure via \"ZipUp\" product; an investor missed a takeover payment","note":"Reopened some withdrawals later, unlike most 2022-cohort peers."}', datetime('now')),
  ('hodlnaut', 'cex', 'Hodlnaut', NULL, 'assets under management', NULL, 191350000, NULL, NULL, '2022-08-08', 'Hodlnaut, a Singapore-based crypto lender, halted withdrawals on August 8, 2022, disclosing a shortfall reported between $189.7 million and $193 million tied to directional trading losses during the 2022 market downturn. Creditors rejected a proposed restructuring in January 2023, sending the company into liquidation; per an EY circular dated March 2026, the wind-down is still ongoing. In May 2026, Singapore authorities charged former CEO Zhu Juntao with six counts of fraud by false representation, alleging he directed staff to publish false claims — on Telegram, in customer emails, and on his personal X account — that Hodlnaut had no direct exposure to the TerraUSD collapse, when it had in fact channeled roughly $317 million in user funds into Terra''s Anchor Protocol. Zhu has disputed all six charges, which remain pending trial as of mid-2026 — this is a criminal charge, not a conviction.', 'Still in liquidation/wind-down per a March 2026 EY circular; the Zhu Juntao fraud case remains pending trial, unresolved.', 'defunct', '[{"title":"Crypto Lender Hodlnaut Freezes Withdrawals Citing Market Conditions — CoinDesk","url":"https://www.coindesk.com/business/2022/08/08/crypto-lender-hodlnaut-freezes-withdrawals-citing-market-conditions"},{"title":"Singapore Charges Former Hodlnaut CEO Zhu Juntao Over Terra Collapse Claims — CoinDesk","url":"https://www.coindesk.com/policy/2026/05/27/singapore-charges-former-hodlnaut-ceo-zhu-juntao-over-terra-collapse-claims"}]', '{"cause_tags":["bank_run"],"hq":"Singapore","shortfall_usd_range":"$189.7M-$193M","withdrawals_halted":"2022-08-08","restructuring_rejected":"Jan 2023 (creditor vote)","status_2026":"still in wind-down per EY circular dated March 2026","individuals":[{"name":"Zhu Juntao","role":"former CEO","status":"charged, NOT convicted","note":"Singapore Police charged him in May 2026 with 6 counts of fraud by false representation, alleging he directed staff to publish false claims (Telegram, customer emails, personal X account) that Hodlnaut had no direct TerraUSD exposure, despite having channeled ~$317M into Terra''s Anchor Protocol. He disputes all charges; case pending trial as of mid-2026, faces up to 20 years per charge if convicted — but is NOT yet convicted. Fact confirmed via WebSearch (CoinDesk, 2026-05-27) since the task material referenced this individual but did not supply the charge details."}]}', datetime('now')),
  ('genesis-global', 'cex', 'Genesis Global Capital/Trading', NULL, 'assets under management', NULL, NULL, NULL, NULL, '2023-01-19', 'Genesis Global Capital/Trading, the DCG-owned crypto lender, filed for Chapter 11 bankruptcy on January 19-20, 2023, driven by lending exposure to Three Arrows Capital and Alameda Research. New York Attorney General Letitia James secured a $2 billion settlement from Genesis, per the NY AG''s official press release. Restructuring ultimately distributed roughly $4 billion through the Chapter 11 plan plus a further $2.2 billion specifically to Gemini Earn users, for a combined total of about $6.2 billion distributed.', 'Wound down through Chapter 11 with substantial creditor distributions completed (~$6.2B total) and a $2B NY AG settlement resolved.', 'defunct', '[{"title":"Genesis Global Files for Bankruptcy Protection — CoinDesk","url":"https://www.coindesk.com/business/2023/01/20/genesis-global-files-for-bankruptcy-protection"},{"title":"Attorney General James Secures Settlement Worth $2 Billion From Crypto Firm Genesis — NY AG","url":"https://ag.ny.gov/press-release/2024/attorney-general-james-secures-settlement-worth-2-billion-crypto-firm-genesis"}]', '{"cause_tags":["bank_run"],"parent":"Digital Currency Group (DCG)","bankruptcy_filed":"2023-01-19/20","trigger":"Three Arrows Capital and Alameda Research lending exposure","ny_ag_settlement_usd":"$2B","total_distributed_usd":"~$6.2B ($4B Ch.11 plan + $2.2B to Gemini Earn users)"}', datetime('now')),
  ('bittrex', 'cex', 'Bittrex', NULL, 'assets under management', NULL, 24000000, NULL, NULL, '2023-05-08', 'Bittrex''s US entity filed for Chapter 11 bankruptcy on May 8, 2023, after the SEC charged it in April 2023 with operating as an unregistered exchange, broker, and clearing agency; US operations ended April 30, 2023, and Bittrex settled with the SEC for $24 million in August 2023. Bittrex Global, the separate international entity, wound down between November 20 and December 4, 2023.', 'Both the US entity and Bittrex Global fully wound down within the same year, driven by US regulatory action.', 'defunct', '[{"title":"US Crypto Exchange Bittrex Files for Bankruptcy in Delaware — CoinDesk","url":"https://www.coindesk.com/policy/2023/05/08/us-crypto-exchange-bittrex-files-for-bankruptcy-in-delaware"},{"title":"Crypto Exchange Bittrex Global to Shut Down — CoinDesk","url":"https://www.coindesk.com/business/2023/11/21/crypto-exchange-bittrex-global-to-shut-down"}]', '{"cause_tags":["regulatory_shutdown"],"sec_charges":"unregistered exchange/broker/clearing agency, April 2023","us_ops_ended":"2023-04-30","bankruptcy_filed_us":"2023-05-08","sec_settlement_usd":24000000,"sec_settlement_date":"2023-08","bittrex_global_wind_down":"2023-11-20 to 2023-12-04"}', datetime('now')),
  ('xeggex', 'cex', 'XeggeX', '2021', 'assets under management', NULL, 80000000, NULL, NULL, '2025-06-27', 'XeggeX was hacked in February 2025 after the CEO''s Telegram account was compromised, leading to a systemic breach; the exchange declared bankruptcy on June 27, 2025. Roughly $80 million across 12,000 users was affected, and the funds were deemed unrecoverable.', 'Bankruptcy declared with funds deemed unrecoverable — no relaunch path.', 'defunct', '[{"title":"XeggeX Exchange Bankruptcy Leaves 12,000 Users $80 Million in Unrecoverable Assets — AInvest","url":"https://www.ainvest.com/news/xeggex-exchange-bankruptcy-leaves-12-000-users-80-million-unrecoverable-assets-2506/"}]', '{"cause_tags":["security_failure","exploit_hack"],"launched":"2021","hack_date":"2025-02","hack_vector":"CEO Telegram account compromise leading to systemic breach","amount_usd":80000000,"users_affected":12000,"bankruptcy_declared":"2025-06-27","recovery_status":"deemed unrecoverable"}', datetime('now')),
  ('ascendex', 'cex', 'AscendEX', NULL, 'assets under management', NULL, 240000000, NULL, NULL, '2026-07-01', 'AscendEX ceased operations on July 1, 2026, after missing the EU''s MiCA compliance licensing deadline. Its reserve balance dropped by roughly $240 million on June 20, 2026 — after a similarly-sized ~$240 million "liquidity injection" roughly two months earlier that apparently did not hold — and on-chain investigator ZachXBT flagged empty hot wallets. Automated withdrawals have been suspended since July 6, 2026, with all requests under manual review and no guarantee on timing or final payout. As of today (July 27, 2026), this remains unresolved: no bankruptcy filing has been confirmed.', 'Still developing and explicitly unresolved as of July 27, 2026 — withdrawals remain suspended under manual review with no committed timeline or payout guarantee, and no bankruptcy filing has been confirmed. Materially different from the fully-collapsed entries in this dataset; do not conflate with a confirmed default.', 'unresolved', '[{"title":"AscendEX Shuts Down After MiCA Miss, Warns Some Withdrawals May Not Be Processed — CryptoSlate","url":"https://cryptoslate.com/ascendex-shuts-down-after-mica-miss-and-warns-some-withdrawals-may-not-be-processed/"},{"title":"Crypto Exchange AscendEX Halts All Operations, Offers No Guarantees on Customer Fund Withdrawals — Crowdfund Insider","url":"https://www.crowdfundinsider.com/2026/07/290550-crypto-exchange-ascendex-halts-all-operations-offers-no-guarantees-on-customer-fund-withdrawals/"}]', '{"cause_tags":["regulatory_shutdown"],"ops_ceased":"2026-07-01","trigger":"missed EU MiCA compliance license deadline (2026-07-01)","reserve_drop_usd":240000000,"reserve_drop_date":"2026-06-20","prior_liquidity_injection":"a similarly-sized ~$240M injection roughly two months earlier that apparently did not hold","flagged_by":"ZachXBT (empty hot wallets)","withdrawals_suspended_since":"2026-07-06","status":"unresolved as of 2026-07-27 — no bankruptcy filing confirmed, no guarantee on timing or final payout"}', datetime('now')),
  ('wazirx', 'cex', 'WazirX', NULL, 'assets under management', NULL, 234900000, NULL, NULL, '2024-07-18', 'WazirX, India''s largest crypto exchange, was hacked on July 18, 2024, in a Lazarus Group-linked breach that compromised a multisig wallet via third-party custodian Liminal, resulting in $234.9 million stolen (only about $3 million was recovered). The exchange shut down for 16 months. It reopened on October 24, 2025 following a restructuring, with users receiving approximately 85% of holdings back in-kind plus 15% as non-tradable "Recovery Tokens" issued in January 2026; WazirX relaunched futures trading in March 2026.', 'Unlike most entries in this dataset, WazirX actually reopened after restructuring and has resumed core services (spot, and as of March 2026, futures) — a genuine, if partial, recovery rather than a full shutdown.', 'recovering', '[{"title":"2 Years of the INR 2000 Cr WazirX Hack: The Money Never Came Back, Neither Did the Founder — CryptoTimes","url":"https://www.cryptotimes.io/2026/07/18/2-years-of-the-inr-2000-cr-wazirx-hack-the-money-never-came-back-neither-did-the-founder/"}]', '{"cause_tags":["exploit_hack","security_failure"],"hq":"India","hack_date":"2024-07-18","attribution":"Lazarus Group-linked breach via third-party custodian Liminal, multisig wallet compromise","amount_stolen_usd":234900000,"amount_recovered_usd":3000000,"shutdown_duration":"16 months","reopened":"2025-10-24","restructuring_terms":"~85% of holdings returned in-kind + 15% as non-tradable \"Recovery Tokens\" (issued Jan 2026)","futures_relaunch":"2026-03"}', datetime('now')),
  ('thodex', 'cex', 'Thodex', NULL, 'assets under management', NULL, NULL, NULL, NULL, '2021-04-21', 'Thodex, a Turkish crypto exchange, collapsed in an exit scam on April 21, 2021, defrauding more than 400,000 users of an estimated $2-2.6 billion. Founder Faruk Fatih Özer fled Turkey, was arrested in Albania in August 2022, extradited, and sentenced to 11,196 years in Turkish prison in September 2023 — a court-convicted case, safe to state as settled fact. Chainalysis called it the largest "rug pull" of 2021.', 'Founder convicted and sentenced; no prospect of the exchange reopening.', 'defunct', '[{"title":"Founder of Failed Crypto Exchange Thodex Arrested in Turkey After 2-Year Run — IBTimes","url":"https://www.ibtimes.com/founder-failed-crypto-exchange-thodex-arrested-turkey-after-2-years-run-3687988"}]', '{"cause_tags":["soft_rug","insider_fraud"],"hq":"Turkey","amount_usd_range":"$2B-$2.6B","users_defrauded":"400,000+","individuals":[{"name":"Faruk Fatih Özer","role":"founder","status":"convicted; sentenced to 11,196 years in Turkish prison, Sept 2023","note":"Court-convicted — safe to state as settled fact. Arrested in Albania Aug 2022, extradited to Turkey."}],"external_characterization":"Chainalysis called it the largest \"rug pull\" of 2021"}', datetime('now')),
  ('fcoin', 'cex', 'FCoin', NULL, 'assets under management', NULL, 127500000, NULL, NULL, '2020-02-17', 'FCoin, a Chinese crypto exchange, became insolvent on February 17, 2020, when founder Zhang Jian announced the exchange was unable to repay roughly 13,000 BTC (an estimated $125-130 million) owed to users. Zhang Jian was never charged or convicted of any crime; researchers — notably AnChain.AI, based on wallet-flow analysis — have suggested the collapse may have been an "exit scam," but that characterization is a researcher allegation, not a legal finding. The founder disappeared, and the matter remains unresolved.', 'Founder disappeared with the matter never legally resolved — no recovery, no reopening, no criminal proceeding on record.', 'defunct', '[{"title":"Crypto Exchange FCoin Insolvent After Revealing up to $130M Bitcoin Shortfall — CoinDesk","url":"https://www.coindesk.com/markets/2020/02/17/crypto-exchange-fcoin-insolvent-after-revealing-up-to-130m-bitcoin-shortfall"}]', '{"cause_tags":["team_abandonment"],"hq":"China","amount_btc":"~13,000 BTC","amount_usd":"~$125-130M","individuals":[{"name":"Zhang Jian","role":"founder","status":"never charged or convicted","note":"\"Exit scam\" is a researcher allegation (AnChain.AI, wallet-flow analysis), NOT a legal finding — phrase as alleged/suggested, never as fact of guilt."}],"insolvency_announced":"2020-02-17"}', datetime('now')),
  ('bitmex', 'cex', 'BitMEX', '2015', 'assets under management', NULL, NULL, NULL, NULL, '2026-07-23', 'BitMEX, one of crypto derivatives trading''s original venues, announced a permanent shutdown on July 23, 2026, after an 11-year run, with all operations ceasing by September 23, 2026 at 04:00 UTC. Notably, BitMEX''s own official announcement did not cite fines or market share — it referenced only a vague "strategic review of the business and the broader crypto industry." Analysts point to roughly $200 million in cumulative US regulatory fines (a 2021 CFTC/FinCEN settlement plus a $100 million Bank Secrecy Act criminal fine in January 2025) and a collapse to under 0.01% market share (roughly $400,000/day in volume, per Kaiko/Reuters data) as the real drivers — but these are analysts'' explanatory context, not BitMEX''s own stated reason, and that distinction is deliberate here. BitMEX ran a failed sale process via investment bank Broadhaven Capital Partners starting in February 2025 with no buyer found, and its CEO, CFO, and Chief Growth Officer all stepped down at the end of June 2026, shortly before the shutdown announcement. Pseudonymous researcher Hasu, quoted via Yahoo Finance, offered a specific theory for why no buyer emerged: BitMEX''s oversized insurance fund (roughly 3,694 BTC plus $30.8 million in USDT) made it financially unattractive to acquire — "It started as the golden goose, and then became the noose," in Hasu''s words.', 'A solvent, voluntary wind-down rather than a crisis collapse — operations continue until the September 23, 2026 cutoff.', 'defunct', '[{"title":"BitMEX Closure — Official Announcement","url":"https://www.bitmex.com/blog/bitmex-closure"},{"title":"BitMEX''s 11-Year Run Comes to an End — CoinDesk","url":"https://www.coindesk.com/markets/2026/07/23/bitmex-s-11-year-run-comes-to-an-end-notifies-users-it-is-ending-operations-in-by-sept-23"},{"title":"3 Real Reasons Why BitMEX Is Shutting Down — Yahoo Finance","url":"https://finance.yahoo.com/markets/crypto/articles/3-real-reasons-why-bitmex-201321849.html"},{"title":"BitMEX Exchange Shuts Down September 23 After $200M Fines, Failed Sale — Tech Times","url":"https://www.techtimes.com/articles/321478/20260724/bitmex-exchange-shuts-down-september-23-after-200m-fines-failed-sale.htm"}]', '{"cause_tags":["regulatory_shutdown","competition"],"launched":"2015","announced":"2026-07-23","operations_cease":"2026-09-23T04:00:00Z","stated_reason":"BitMEX''s own announcement cited only a vague \"strategic review of the business and the broader crypto industry\" — no fines or market share mentioned","analyst_context":{"cumulative_us_fines_usd":"~$200M (2021 CFTC/FinCEN settlement + $100M BSA criminal fine, Jan 2025)","market_share":"<0.01% (~$400K/day volume per Kaiko/Reuters)","note":"This is analysts'' explanatory context, not BitMEX''s own stated reason — kept explicitly distinct."},"failed_sale_process":{"bank":"Broadhaven Capital Partners","started":"2025-02","outcome":"no buyer found"},"leadership_departures":"CEO, CFO, and Chief Growth Officer all stepped down end of June 2026","insurance_fund":"~3,694 BTC + $30.8M USDT","hasu_quote":{"attributed_to":"Hasu (pseudonymous researcher), via Yahoo Finance","quote":"It started as the golden goose, and then became the noose.","theory":"The oversized insurance fund made BitMEX financially unattractive to acquire — a specific theory for why the sale process found no buyer."}}', datetime('now')),
  ('bitmart', 'cex', 'BitMart', '2017', 'assets under management', NULL, NULL, NULL, NULL, '2026-07-26', 'BitMart announced a phased shutdown on July 26, 2026 at 01:30 UTC, after roughly nine years of operation (per CoinDesk): registrations, deposits, and new orders were suspended immediately, all trading is set to end August 26, 2026, and the full platform shuts down January 31, 2027. The BMX token crashed 58% on the announcement. Like BitMEX, BitMart cited only vague "market conditions and strategy" rather than a specific cause. In the 24 hours after the announcement, only 58 wallets withdrew a combined roughly $805,000, per Lookonchain, including an 8-hour window with zero processed withdrawals; BitMart''s stated explanation was enhanced security/identity review. BitMart had already restricted withdrawals on 239 linked accounts back in May 2026, two months before this announcement — a possible earlier warning sign. Former Global CEO Nenter "Nathan" Chow says he was informed on July 24 that his employment was being terminated with immediate offboarding, and states he "played no role in the wind-down decision" and learned of it only when it became public; this account is independently reported by Frank Chaparro of The Block, not solely Chow''s own claim, though who ordered his removal and why remains unresolved and speculative in the reporting. Separately, and unrelated to this week''s shutdown, BitMart suffered a roughly $200 million security breach in December 2021 involving a compromised private key on its Ethereum/BSC hot wallets.', 'The real cause of the shutdown remains unresolved as of today — BitMart''s own language ("market conditions and strategy") mirrors BitMEX''s vague framing, the thin post-announcement withdrawal activity and the prior May 2026 account restrictions raise questions, and the ousted CEO''s account (corroborated by The Block) adds an unexplained internal-governance dimension. Full platform shutdown is not until January 31, 2027, so more may surface before this fully resolves.', 'defunct', '[{"title":"Crypto Exchange BitMart to Shut Down After Nine Years, BMX Token Crashes 58% — CoinDesk","url":"https://www.coindesk.com/markets/2026/07/26/crypto-exchange-bitmart-to-shut-down-after-nine-years-bmx-token-crashes-58"},{"title":"BitMart Exit Sparks Concerns as Withdrawals Trickle Out After Shutdown Notice — CryptoTimes","url":"https://www.cryptotimes.io/2026/07/27/bitmart-exit-sparks-concerns-as-withdrawals-trickle-out-after-shutdown-notice/"},{"title":"BitMart to Wind Down Trading Platform as Global CEO Says He Was Not Consulted — The Block","url":"https://www.theblock.co/post/409670/bitmart-to-wind-down-trading-platform-as-global-ceo-says-he-was-not-consulted"},{"title":"BitMart''s Sudden Shutdown Triggers Withdrawal Delays and On-Chain Panic — CryptoSlate","url":"https://cryptoslate.com/bitmarts-sudden-shutdown-triggers-withdrawal-delays-and-on-chain-panic-echoing-the-ghosts-of-2022/"}]', '{"cause_tags":[],"note_on_cause_tags":"Deliberately left minimal/empty — the real cause of this shutdown is unresolved as of the reporting available; see why/outlook for the nuance rather than a causal tag.","launched":"2017","announced":"2026-07-26T01:30:00Z","phase_out":{"registrations_deposits_new_orders_suspended":"immediately (2026-07-26)","trading_ends":"2026-08-26","full_shutdown":"2027-01-31"},"bmx_token_reaction":"-58% on announcement","stated_reason":"\"market conditions and strategy\" (vague, no specific cause given — same register as BitMEX)","post_announcement_withdrawals":{"window":"24 hours post-announcement","wallets":58,"total_usd":805000,"source":"Lookonchain","note":"Included an 8-hour window with zero processed withdrawals; BitMart''s stated explanation was enhanced security/identity review."},"prior_warning_sign":"BitMart restricted withdrawals on 239 linked accounts in May 2026, two months before the shutdown announcement","individuals":[{"name":"Nenter \"Nathan\" Chow","role":"former Global CEO","status":"not accused of wrongdoing; disputes involvement in the wind-down decision","note":"Chow says he was informed July 24, 2026 that his employment was being terminated with immediate offboarding, and states he played no role in the wind-down decision and learned of it only publicly. Independently reported by Frank Chaparro of The Block, not solely Chow''s own claim — citable on that basis. Who ordered his removal and why remains unresolved and speculative in the reporting; do not assert a cause."}],"unrelated_history":"~$200M security breach in Dec 2021 (compromised private key, Ethereum/BSC hot wallet) — background context, unrelated to the 2026 shutdown"}', datetime('now'));

-- ============================== mid_exchanges (kind='dex'/'cex') ==============================

INSERT OR REPLACE INTO mid_exchanges (slug, kind, name, launched, metric_label, metric, verdict, why_stuck, outlook, profile, sources, updated_at) VALUES
  ('sushiswap', 'dex', 'SushiSwap', '2020-08', 'TVL', 73700000, 'declining',
  'SushiSwap has bled TVL for four straight years — from a $7.04B peak in Nov 2021 to $73.7M today, roughly a -99.0% drawdown per DefiLlama — as liquidity migrated to newer AMM designs and concentrated-liquidity competitors across its 40+ deployed chains. That thin liquidity became visible in the worst way on Mar 12 2026, when a $50M USDT swap routed through a Sushi pool holding only about $73K in liquidity, causing roughly 99.9% slippage and drawing renewed scrutiny of how little real depth remains in its pools.',
  'Sushi still functions and retains brand recognition and multi-chain reach, but nothing in its recent history points to organic liquidity returning; expect continued slow decline and periodic reputational hits like the March 2026 slippage incident rather than a reversal.',
  '{"success_factors_missing": ["no_liquidity_moat", "declining_volume"]}',
  '[{"title": "DefiLlama — SushiSwap", "url": "https://defillama.com/protocol/sushiswap"}, {"title": "Aave, Swap DeFi Slippage: $50 Million USDT, CoW Protocol, SushiSwap MEV Bots", "url": "https://www.fintechweekly.com/news/aave-swap-defi-slippage-50-million-usdt-cow-protocol-sushiswap-mev-bots-march-2026"}]',
  datetime('now')),
  ('dodo-amm', 'dex', 'DODO AMM', '2020-08', 'TVL', 12100000, 'declining',
  'DODO''s proactive-market-maker (PMM) model was a genuine innovation in 2021-22, but concentrated-liquidity AMMs and aggregators have since outcompeted it on capital efficiency and routing. TVL has fallen from a $451.9M peak in Jan 2022 to $12.1M today (roughly -97.3%), and active LPs fell from 4,000+ in 2022 to around 1,000 by 2025.',
  'With both liquidity and LP counts still trending down and no differentiated product edge left versus concentrated-liquidity competitors, DODO looks likely to keep shrinking rather than recover share.',
  '{"success_factors_missing": ["competition", "no_liquidity_moat"]}',
  '[{"title": "DefiLlama — DODO", "url": "https://defillama.com/protocol/dodo-amm"}]',
  datetime('now')),
  ('osmosis', 'dex', 'Osmosis DEX', '2021-06', 'TVL', 12300000, 'declining',
  'Osmosis, the flagship DEX of the Cosmos ecosystem, has fallen from a $1.83B TVL peak in Mar 2022 to $12.3M today (roughly -99.3%), tracking a broader Cosmos-wide contraction — ATOM itself was down roughly 90% from its peak by Aug 2025 — rather than any Osmosis-specific product failure.',
  'Osmosis''s fate is tied tightly to the Cosmos ecosystem''s own relevance; without a broader Cosmos/IBC revival, its liquidity is unlikely to meaningfully recover.',
  '{"success_factors_missing": ["declining_volume", "no_liquidity_moat"]}',
  '[{"title": "DefiLlama — Osmosis DEX", "url": "https://defillama.com/protocol/osmosis-dex"}]',
  datetime('now')),
  ('balancer', 'dex', 'Balancer', '2021-05', 'TVL', 55800000, 'declining',
  'Balancer''s V2 TVL has collapsed from a $2.26B peak in Nov 2021 to roughly $55.8M today — commonly cited around -98.7%; an independent recomputation from those two raw figures lands a little lower, so treat the precise decimal as approximate rather than exact. On top of that multi-year bleed, Balancer suffered a serious Nov 3 2025 access-control exploit that drained roughly $128M across 9 chains, also hitting forks like Beets/Beethoven X, and V3 TVL kept falling afterward.',
  'Unlike most of this list, Balancer''s most recent blow was a direct hack rather than a slow liquidity exit, which makes trust-rebuilding harder in the near term; absent a clean security track record post-incident, TVL is likely to keep drifting down.',
  '{"success_factors_missing": ["no_liquidity_moat", "exploit_hack"]}',
  '[{"title": "Hack Drains Over $100 Million From Crypto Protocol Balancer", "url": "https://www.bloomberg.com/news/articles/2025-11-03/hack-drains-over-100-million-from-crypto-protocol-balancer"}]',
  datetime('now')),
  ('bancor', 'dex', 'Bancor', '2017-06', 'TVL', 26200000, 'declining',
  'Bancor''s V2.1 TVL has fallen from a $2.42B peak in May 2021 to $26.2M today — a roughly 98.9% drawdown by direct calculation from those two figures. The defining moment was pausing its Impermanent Loss Protection in Jun 2022 during the Celsius/Terra liquidity crisis, a decision that drew heavy user backlash right when it was needed most; liquidity never returned to scale afterward.',
  'As the original AMM pioneer, Bancor retains some brand recognition, but the IL-protection pause broke trust with exactly the LPs it needed to retain, and nothing since has rebuilt that liquidity base.',
  '{"success_factors_missing": ["no_liquidity_moat", "declining_volume"]}',
  '[{"title": "Bancor Suspends DeFi Impermanent Loss Protection When Users Need It Most", "url": "https://protos.com/bancor-suspends-defi-impermanent-loss-protection-when-users-need-it-most/"}]',
  datetime('now')),
  ('spookyswap', 'dex', 'SpookySwap', '2021-04', 'TVL', 713000, 'declining',
  'SpookySwap, once the largest DEX on Fantom, has fallen from a $1.66B TVL peak in Jan 2022 to roughly $713K today (about -99.96%), closely tracking Fantom''s own Jan 2025 rebrand to "Sonic" — incentives and liquidity have shifted toward Sonic-native protocols, leaving the legacy Fantom-branded DEX increasingly hollowed out.',
  'Its fate is tied to a chain that effectively renamed and repositioned itself away from it; without a Sonic-native relaunch capturing meaningful share, SpookySwap''s liquidity is likely to keep fading.',
  '{"success_factors_missing": ["competition", "declining_volume"]}',
  '[{"title": "DefiLlama — SpookySwap V2", "url": "https://defillama.com/protocol/spookyswap-v2"}]',
  datetime('now')),
  ('htx', 'cex', 'HTX (formerly Huobi)', NULL, 'quarterly spot trading volume', 133600000000, 'declining', 'HTX (formerly Huobi), controlled by Justin Sun, is being squeezed on two fronts: quarterly spot trading volume fell 55% to $133.6 billion in Q1 2026, and the UK sanctioned the Sun-controlled entity in May 2026 — the first exchange designated under the UK''s Russia-sanctions framework, citing over $1.5 billion in Russia-linked transactions. The UK FCA had already gotten Apple and Google to remove HTX''s apps from UK stores in February 2026. HTX blocks the EU entirely post-MiCA (effective July 1, 2026) and carries long-standing bans across the US, mainland China, Hong Kong, the UK, and Singapore, nearing 40 blocked jurisdictions in total.', 'Facing an expanding map of blocked jurisdictions (UK sanctions, EU MiCA exclusion, long-standing US/China/HK/Singapore bans) with no clear path back into any of them; the volume decline looks structural rather than cyclical.', '{"cause_tags":["regulatory","declining_volume"],"q1_2026_spot_volume_usd":133600000000,"q1_2026_spot_volume_change":"-55%","uk_sanction_date":"2026-05","uk_sanction_note":"first exchange designated under the UK''s Russia-sanctions framework; $1.5B+ in Russia-linked transactions cited","uk_app_store_removal":"Feb 2026 (FCA got Apple/Google to remove HTX apps from UK stores)","eu_mica_status":"blocks the EU entirely post-MiCA (effective 2026-07-01)","other_bans":"long-standing bans in US, mainland China, Hong Kong, UK, Singapore — nearing 40 blocked jurisdictions total"}', '[{"title":"Crypto Exchange Report Q1 2026 — TokenInsight","url":"https://tokeninsight.com/en/research/reports/crypto-exchange-report-q1-2026"},{"title":"How Justin Sun''s HTX Ended Up at the Center of a UK Sanctions Crackdown — Coinpaper","url":"https://coinpaper.com/17337/how-justin-sun-s-htx-ended-up-at-the-center-of-a-uk-sanctions-crackdown"}]', datetime('now')),
  ('bithumb', 'cex', 'Bithumb', NULL, 'daily trading volume', 599770000, 'declining', 'Bithumb, once South Korea''s leading exchange, is losing ground on two fronts: quarterly volume fell 31.3% in Q1 2026 (121.9 trillion won to 83.9 trillion won), and daily average volume fell 48.5% from January 1 to May 20, 2026, to roughly $599.77 million/day. It is also losing market share to Upbit, which now captures about 72% of the Korean youth market and, combined with Bithumb, roughly 96% of all Korean exchange volume — leaving Bithumb the smaller of the two dominant domestic players.', 'The volume decline looks share-driven — losing ground to Upbit specifically — rather than a market-wide contraction, since the two together still hold ~96% of Korean CEX volume.', '{"cause_tags":["declining_volume","competition"],"q1_2026_volume_change":"-31.3% (121.9T won to 83.9T won)","daily_avg_volume_change":"-48.5% (Jan 1-May 20 2026)","daily_avg_volume_usd":599770000,"competitor":"Upbit — ~72% of Korean youth market; Upbit+Bithumb ~96% of Korean CEX volume combined"}', '[{"title":"Bithumb Volume Falls in South Korea Q1 — CryptoRank","url":"https://cryptorank.io/news/feed/ffb44-bithumb-volume-falls-south-korea-q1"}]', datetime('now')),
  ('kucoin', 'cex', 'KuCoin', NULL, 'quarterly futures trading volume', 84000000000, 'declining', 'KuCoin pleaded guilty to operating an unlicensed money-transmitting business and paid a DOJ fine of more than $297 million in January 2025, agreeing to exit the US market for at least two years. Its futures trading volume fell 61% month-over-month to $84 billion in Q2 2026 — the largest decline among major futures venues that quarter.', 'The scale of the futures-volume decline, more than a year after the DOJ settlement, suggests the market impact is still compounding rather than a one-time hit that has already been absorbed.', '{"cause_tags":["regulatory","declining_volume"],"doj_settlement_usd":297000000,"guilty_plea_date":"2025-01-28","us_market_exit":"agreed to exit US market for at least 2 years","q2_2026_futures_volume_usd":84000000000,"q2_2026_futures_volume_change":"-61% MoM, the largest decline among major futures venues that quarter"}', '[{"title":"KuCoin Hit With Nearly $300 Million Fine After Pleading Guilty to US DOJ Charges — CoinDesk","url":"https://www.coindesk.com/policy/2025/01/28/kucoin-hit-with-nearly-usd300-million-fine-after-pleading-guilty-to-u-s-doj-charges"}]', datetime('now')),
  ('okx', 'cex', 'OKX (Seychelles entity)', NULL, 'operational status', NULL, 'pivoting', 'OKX''s Seychelles operating entity — not the overall OKX brand, which remains a top-10 global exchange — pleaded guilty to unlicensed money transmission and paid a penalty of more than $504 million in February 2025. To re-enter the US market, OKX had to stand up a wholly separate US entity with regional headquarters in San Jose, which launched in April 2025. This is regulatory restructuring forced on one entity, not a decline of the OKX brand as a whole.', 'A regulatory restructuring forced by the Seychelles entity''s guilty plea, with the broader OKX brand continuing to operate globally through the new US entity and its existing international business — pivoting, not declining.', '{"cause_tags":["regulatory"],"entity_note":"Aux Cayes Fintech Co. Ltd., the Seychelles entity operating OKX, pleaded guilty; the broader OKX brand remains active. Do not attribute the conduct to the separate US entity.","penalty_usd":504000000,"guilty_plea_date":"2025-02-24","new_us_entity":"Separate US exchange and wallet operation with San Jose regional headquarters, announced April 2025"}', '[{"title":"OKX Pleads Guilty and Agrees to Pay More Than $500M — US DOJ (SDNY)","url":"https://www.justice.gov/usao-sdny/pr/okx-pleads-guilty-violating-us-anti-money-laundering-laws-and-agrees-pay-penalties"},{"title":"Bringing OKX to America — OKX US","url":"https://www.okx.com/en-us/learn/bringing-okx-to-the-united-states-a-new-era-for-crypto-and-web3-innovation"}]', datetime('now'));

-- Explicit comparison dimensions. A numeric USD field is not automatically
-- comparable: TVL, point-in-time token price, trading volume, liabilities and
-- documented losses answer different questions. These fields are consumed by
-- the API to keep trend cohorts honest and by venue filters to prevent lenders,
-- brokers and custodians from being mislabeled as centralized exchanges.
UPDATE dead_exchanges
SET metric_type = CASE
  WHEN metric_label = 'TVL' THEN 'tvl'
  WHEN metric_label LIKE '%token price' THEN 'token_price'
  WHEN kind = 'cex' AND current_metric IS NOT NULL THEN 'loss_exposure'
  ELSE 'operational_status'
END,
metric_unit = CASE WHEN metric_label LIKE '%token price' THEN 'usd_per_token' ELSE 'usd' END;

UPDATE dead_exchanges
SET metric_label = 'documented loss / exposure'
WHERE kind = 'cex' AND metric_type = 'loss_exposure';

UPDATE dead_exchanges SET venue_type = 'lender'
WHERE slug IN ('celsius', 'blockfi', 'vauld', 'hodlnaut', 'genesis-global');
UPDATE dead_exchanges SET venue_type = 'broker' WHERE slug = 'voyager-digital';
UPDATE dead_exchanges SET venue_type = 'custodian' WHERE slug = 'prime-trust';

UPDATE mid_exchanges
SET metric_type = CASE
  WHEN metric_label = 'TVL' THEN 'tvl'
  WHEN metric_label LIKE '%trading volume' THEN 'trading_volume'
  ELSE 'operational_status'
END,
metric_unit = 'usd';

-- ============================== graveyard_meta narrative rows ==============================

INSERT OR REPLACE INTO graveyard_meta (k, v, updated_at) VALUES
  ('dex_trends',
  'ATTACK-VECTOR BREAKDOWN. Across the 19 dead/dying DEXs profiled here, 52.6% failed to a pure smart-contract logic exploit (KyberSwap Elastic, Platypus Finance, Deus Finance, Mango Markets, Mirror Protocol, Bunni, WaultSwap, GMX V1, Uranium Finance, and Balancer''s 2025 incident), 31.6% declined or wound down on pure liquidity/incentive collapse with no hack at all (SushiSwap, DODO, Osmosis, Bancor, SpookySwap, and Saddle Finance, the last of which wound down by DAO vote rather than exploit), 10.5% failed to a governance or founder-exit event (Solidly, Serum), and 5.3% to a bridge/cross-chain compromise (SpiritSwap). Zero of the 19 trace to a straightforward admin-key compromise historically — a notable contrast against the live incidents below, several of which are exactly that.

TVL DRAWDOWN SEVERITY. Across the 9 dead/dying DEXs in this set with clean peak-vs-current TVL figures, the mean drawdown is -99.2% and the median -99.3%. Every one has blown past the -90% threshold Chaindump uses to call a chain "dead," several by 9 or more points — in DEXs specifically, "stuck and declining" and "actually dead" blur together at the tail far more than the raw verdict labels suggest.

THIS WEEK (Jul 20-27, 2026) — developing, unresolved incidents to watch, not verdicts; none of the projects below have been given a dead or declining call. A cluster of DEX-adjacent bridge exploits hit in quick succession: the Wanchain-Cardano bridge lost roughly $10-13M (Jul 20-21) to a signed-message-encoding flaw; AFX Trade''s own Arbitrum perp-DEX bridge lost $24.15M (Jul 22) after 5 compromised validator keys reached quorum; and the Verus-Ethereum bridge was hit a second time (Jul 23, $7.54M) via the same vulnerability class as an $11.58M exploit exactly 66 days earlier that was supposedly already fixed, per Blockaid via CoinDesk. Separately, the WEMIX$ stablecoin lost $5.22M (Jul 26) to a compromised admin key, forcing WEMIX to suspend its DEX/bridge infrastructure, and Garden Finance lost roughly $450K (Jul 26) — notably, Garden states its own smart contracts were not compromised; a single independent solver''s off-chain database was manipulated, its second such solver-compromise incident in nine months after an ~$11.4M incident in Oct 2025. Per CryptoTimes, the week of Jul 19-25 2026 saw at least six exploits (including Allbridge and B² Network, not profiled individually here since they have not been independently verified to the same bar as the incidents above) totaling over $47M.

CONTEXT, NOT PANIC. Bridge exploits are a documented, recurring pattern across all of 2026, not a one-week anomaly — PeckShield tracked roughly $328.6M across 8 bridge exploits through mid-May 2026 alone. This week is a real, unusually dense spike within that ongoing trend (roughly $42-45M in bridge losses across just four days), but it reads as an intensification of a known pattern rather than an unprecedented event, and neither framing should be dropped in favor of the other.',
  datetime('now')),
  ('dex_success_factors',
  'The starkest finding in this dataset is that 31.6% of dead or dying DEXs never suffered an attack at all — SushiSwap, DODO, Osmosis, Bancor, SpookySwap and Saddle Finance all declined or wound down purely because the liquidity underneath them was never really theirs to keep. It was mercenary capital chasing whichever incentive program paid the highest APR that month, and it left the moment incentives dried up or a competitor with better capital efficiency (typically a concentrated-liquidity AMM) showed up.

What separates a DEX that survives a cycle from one that becomes a statistic is whether it ever converted that farmed liquidity into a durable, fee-generating user base. Uniswap, Curve and Aerodrome all retained meaningfully organic trading volume through the cycles that emptied out this graveyard — volume that exists because people actually want to trade there, not because a farming program is paying them to park capital. That is a genuine liquidity moat; incentive-farmed TVL is a rental, not an asset, and every DEX in that 31.6% found that out the same way.

The practical takeaway: TVL growth funded primarily by emissions should be read as a warning sign to watch, not a milestone to celebrate, until a protocol demonstrates it can hold roughly its level once the emissions taper off.',
  datetime('now')),
  ('cefi_mixed_trends_archive', 'ARCHIVED — NOT FOR PUBLIC CEX AGGREGATION. This research note mixes centralized exchanges, lenders, brokers, and custodians and must be rebuilt as venue-type cohorts before publication. Across nine measured centralized-platform collapses in this dataset — CoinFLEX (1 day), Voyager (4 days), FTX (6 days), BlockFi (8 days), AscendEX (11 days), Vauld (22 days), Hodlnaut (25 days), Celsius (31 days), and Zipmex (37 days), each measured from the first public sign of trouble to the withdrawal freeze — the mean time-to-collapse is 16.1 days and the median is 11 days. 33% of these cases froze withdrawals within a week of the first public sign of trouble. The slower cases in this set did not simply take longer for the same reason: Celsius, Zipmex, and to a lesser extent Hodlnaut each initially issued public statements claiming they could absorb the shock, and were wrong. That claim itself looks like a leading indicator of a roughly three-to-five-week runway before the freeze, not of days.

Two entries in this dataset are qualitatively different from the rest: BitMEX and BitMart are the only solvent, voluntary wind-downs here, rather than crisis collapses forced by a bank run, a hack, or a regulator. Both also used strikingly similar, vague language to announce themselves — BitMEX''s own statement cited only a "strategic review of the business and the broader crypto industry," and BitMart cited "market conditions and strategy" — neither naming a specific precipitating cause. That is a real, if small (n=2), pattern worth naming, especially set against the transparent cases in this dataset: Voyager named the Three Arrows Capital default explicitly, and BlockFi named its ~$1.2B FTX/Alameda exposure explicitly, in each case as the stated reason for the filing.

The stated causes behind CEX deaths have also shifted era to era. Bank-run/contagion dynamics were the dominant cause among the 2022-era CEX deaths in this dataset (Voyager, CoinFLEX, Vauld, Zipmex, Hodlnaut, Genesis all carry a bank-run tag) but are essentially absent since. Regulatory failure, by contrast, caused none of the 2022-era collapses in this dataset but is now the largest cause bucket among the 2023-2026 cohort — Bittrex, AscendEX, and BitMEX are all tagged as regulatory shutdowns. Fraud-driven causes (insider fraud, commingled funds — FTX, Celsius, and QuadrigaCX as alleged) were relatively more common in the earlier cohort than the later one. This dataset is small enough that these shares should be read as directional, not statistically definitive, but the shift from "ran out of money in a market crash" to "regulators shut it down" is a real change in why exchanges die.

AscendEX is a confirmed casualty of the EU''s Markets in Crypto-Assets (MiCA) regime: it ceased operations after missing the July 1, 2026 compliance deadline. It is not alone — coverage via Yahoo Finance and Reuters has also reported that Knaken, a Dutch exchange, failed to obtain MiCA authorization and had Dutch prosecutors seek its bankruptcy in June 2026. The Knaken case has not been independently verified to the same bar as the rest of this dataset, so it is noted here as reported, not confirmed. Taken together, though, the two cases suggest MiCA''s licensing deadline is starting to actively cull exchanges that could not or did not comply, not merely deter new entrants.

One comparison in this dataset is genuinely striking, and worth stating precisely so the two numbers are not conflated: Mt. Gox''s 850,000 BTC, worth an estimated $473-500 million when it disappeared in 2014, would be worth roughly $55.6 billion at bitcoin''s July 27, 2026 price of about $65,359 — this is what the lost capital would be worth today, not a restatement of the original 2014 loss. On that basis, the value of what Mt. Gox lost, measured in today''s terms, is roughly 7x larger than FTX''s $8 billion customer shortfall — a reminder that in an asset this volatile, the true cost of a decade-old custodial failure keeps growing long after the case itself is closed.', datetime('now')),
  ('cex_success_factors', 'What distinguishes a CEX that survives serious regulatory or market pressure from one that winds down looks less about the size of the penalty and more about what the exchange does immediately after it lands. OKX''s Seychelles entity pleaded guilty to unlicensed money transmission and paid a $504 million-plus penalty in February 2025 — a serious blow — but OKX responded by standing up a wholly separate, FinCEN-registered US entity (OKX INC., San Jose) within about two months, re-entering the market on a compliant footing rather than exiting it. The overall OKX brand remains a top-10 global exchange throughout.

Bybit offers a similar pattern from the other direction: rather than wait for a MiCA compliance deadline to force a shutdown — the fate that met AscendEX, and reportedly Knaken — Bybit proactively built and licensed bybit.eu ahead of the deadline, choosing to invest in compliance infrastructure before it became existential. In both cases, the exchanges treated a regulatory requirement as a cost of staying in a market, not a reason to leave it.

The contrasting pattern in this dataset — vague "strategic review" or "market conditions and strategy" language preceding a wind-down, as seen with BitMEX and BitMart — reads as the opposite instinct: an announcement made after the decision to exit is essentially final, without the specific-cause transparency that, for example, Voyager and BlockFi offered when naming their precipitating exposures. Whether that vagueness reflects an unresolved internal cause, legal caution, or simply a wish to avoid a panic, the practical effect is the same: it leaves users and observers unable to assess whether the same risk could recur elsewhere — precisely the information a compliance-forward pivot like OKX''s or Bybit''s is designed to supply instead.', datetime('now'));
